import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { iso, JOB_COLUMNS, MAX_ATTEMPTS, type JobRow } from './store.ts';

const STEP_MS = 100;
const IDLE_MS = 200;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 1000;
const TRANSIENT_ERROR = 'transient failure';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function writeHeartbeat(ts: number): void {
  db.prepare("UPDATE heartbeat SET ts = ? WHERE name = 'worker'").run(ts);
}

/**
 * Attempts that were running when a previous worker died never finished. Requeue them and roll
 * back the attempt count, so the re-run takes the same attempt number and does not consume a retry.
 * This assumes a single worker process.
 */
function recoverInterrupted(): void {
  const changed = db
    .prepare(
      "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed = 0, next_run_at = 0, updated_at = ? WHERE status = 'running'",
    )
    .run(iso(Date.now())).changes;
  if (Number(changed) > 0) console.log(`requeued ${changed} interrupted job(s)`);
}

/** Atomically takes the oldest eligible queued job and marks it running for a new attempt. */
function claimNext(): JobRow | undefined {
  const now = Date.now();
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db
      .prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1`)
      .get(now) as unknown as JobRow | undefined;
    if (row) {
      db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?").run(iso(now), row.seq);
    }
    db.exec('COMMIT');
    if (!row) return undefined;
    return { ...row, status: 'running', attempts: row.attempts + 1, completed: 0 };
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

/** Runs one attempt of a claimed job. `job.attempts` already counts this attempt. */
async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    if (attempt < MAX_ATTEMPTS) {
      db.prepare("UPDATE jobs SET status = 'queued', error = NULL, completed = 0, next_run_at = ?, updated_at = ? WHERE seq = ?").run(
        Date.now() + RETRY_DELAY_MS,
        iso(Date.now()),
        job.seq,
      );
    } else {
      db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, completed = 0, next_run_at = 0, updated_at = ? WHERE seq = ?").run(
        TRANSIENT_ERROR,
        iso(Date.now()),
        job.seq,
      );
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    // Shutting down mid-job: leave the job running. The next worker start requeues it.
    if (stopping) return;
    db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?').run(step, iso(Date.now()), job.seq);
  }

  db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, next_run_at = 0, updated_at = ? WHERE seq = ?",
  ).run(job.input.toUpperCase(), iso(Date.now()), job.seq);
}

async function main(): Promise<void> {
  recoverInterrupted();
  writeHeartbeat(Date.now());
  const heartbeat = setInterval(() => {
    try {
      writeHeartbeat(Date.now());
    } catch (err) {
      console.error('heartbeat failed:', err);
    }
  }, HEARTBEAT_MS);

  console.log('worker started');
  while (!stopping) {
    try {
      const job = claimNext();
      if (job) await processJob(job);
      else await sleep(IDLE_MS);
    } catch (err) {
      console.error('worker error:', err);
      await sleep(IDLE_MS);
    }
  }

  clearInterval(heartbeat);
  writeHeartbeat(0);
  db.close();
  console.log('worker stopped');
}

main().catch((err: unknown) => {
  console.error('worker failed:', err);
  process.exit(1);
});

