  if (key.value !== null) {
    const existing = findJobRowByKey(db, key.value);
    if (existing) {
      const samePayload =
        existing.input === value.input && existing.steps === value.steps && existing.fail_attempts === value.failAttempts;
      if (samePayload) return send(res, 200, toJob(existing));
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
  }

